function $(s){return document.querySelector(s);}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8);}
function round2(n){return Math.round(n*100)/100;}
function dots(n){return String(Math.round(Math.abs(n))).replace(/\B(?=(\d{3})+(?!\d))/g,'.');}
function fmt(n){return (n<0?'−':'')+'Rp '+dots(n);}
function fmtQty(q){return String(round2(q)).replace('.',state.lang==='id'?',':'.');}
function fmtShort(n){var dec=state.lang==='id'?',':'.';if(n>=1e6) return 'Rp '+(n/1e6).toFixed(1).replace(/\.0$/,'').replace('.',dec)+T('jt');if(n>=1e3) return 'Rp '+Math.round(n/1e3)+T('rb');return 'Rp '+Math.round(n);}
function digitsOnly(s){return String(s).replace(/\D/g,'').replace(/^0+(?=\d)/,'').slice(0,10);}
function T(k){var dict=I18N[state.lang]||I18N.id;var v=dict[k];if(typeof v==='function') return v.apply(null,Array.prototype.slice.call(arguments,1));return v==null?k:v;}
function stepOf(u){return (u==='kg'||u==='liter')?0.5:1;}
function nameOf(it){if(it.tpl&&STAPLES[it.tpl]) return STAPLES[it.tpl][state.lang]||STAPLES[it.tpl].id;return it.name||'';}
function fromTpl(k,qty,done){var s=STAPLES[k];return {id:uid(),tpl:k,cat:s.cat,qty:qty==null?s.qty:qty,unit:s.unit,price:s.price,done:!!done};}
function monthKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');}
function keyToDate(k){var p=k.split('-');return new Date(Number(p[0]),Number(p[1])-1,1);}
function shiftKey(k,d){var dt=keyToDate(k);dt.setMonth(dt.getMonth()+d);return monthKey(dt);}
function monthLabel(k,short){var loc=state.lang==='id'?'id-ID':'en-US';try{return new Intl.DateTimeFormat(loc,{month:short?'short':'long',year:'numeric'}).format(keyToDate(k));}catch(e){return k;}}
var storageOk=true;
function load(){try{var raw=window.localStorage.getItem(STORE_KEY);if(!raw) return null;var d=JSON.parse(raw);return d&&typeof d==='object'&&d.months?d:null;}catch(e){storageOk=false;return null;}}
var suppressNotify=false,lastSig=null;
function sigOf(s){var c={};Object.keys(s).forEach(function(k){if(k!=='updatedAt') c[k]=s[k];});return JSON.stringify(c);}
function save(){var sig=sigOf(state);var changed=sig!==lastSig;lastSig=sig;if(changed&&!suppressNotify) state.updatedAt=Date.now();if(storageOk){try{window.localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch(e){storageOk=false;}}if(changed&&!suppressNotify&&window.BB_onChange) window.BB_onChange(state);}
(function testStorage(){try{window.localStorage.setItem(STORE_KEY+'-t','1');window.localStorage.removeItem(STORE_KEY+'-t');}catch(e){storageOk=false;}})();
var todayKey=monthKey(new Date());
var state=load();
if(!state){state={lang:'id',months:{}};state.months[todayKey]={budget:1500000,items:SEED.map(function(s){return fromTpl(s[0],s[1],false);})};}
if(state.lang!=='id'&&state.lang!=='en') state.lang='id';
if(!Array.isArray(state.quick)) state.quick=[];
if(!Array.isArray(state.quickHidden)) state.quickHidden=[];
lastSig=sigOf(state);
var view={key:todayKey,cat:'all',q:'',hideDone:false,sort:'cat'};
var lastAddedId=null,editingId=null,focusFid=null;
var sortables=[];
function inheritBudget(k){var keys=Object.keys(state.months).sort(),best=null;keys.forEach(function(kk){if(kk<k&&state.months[kk].budget>0) best=state.months[kk].budget;});if(best==null&&keys.length) best=state.months[keys[keys.length-1]].budget;return best||1500000;}
function cur(){if(!state.months[view.key]) state.months[view.key]={budget:inheritBudget(view.key),items:[]};var m=state.months[view.key];if(!Array.isArray(m.items)) m.items=[];return m;}
function totals(m){var p=0,s=0,d=0;m.items.forEach(function(it){var v=it.qty*it.price;p+=v;if(it.done){s+=v;d++;}});return {planned:p,spent:s,done:d,count:m.items.length};}
function prevKeyWithItems(){var best=null;Object.keys(state.months).sort().forEach(function(k){if(k<view.key&&state.months[k].items&&state.months[k].items.length) best=k;});return best;}
function findItem(id){var a=cur().items;for(var i=0;i<a.length;i++) if(a[i].id===id) return a[i];return null;}
function snapshotDone(){return cur().items.map(function(it){return {id:it.id,done:it.done};});}
function restoreDone(snap){snap.forEach(function(s){var it=findItem(s.id);if(it) it.done=s.done;});render();}
var listEl=$('#list'),chipsEl=$('#chips'),quickEl=$('#quick'),chartEl=$('#chart');
var searchEl=$('#search'),hideDoneEl=$('#hideDone'),bulkToggle=$('#bulkToggle'),bulkBar=$('#bulkBar'),bulkLabel=$('#bulkLabel'),bulkCount=$('#bulkCount'),reorderHint=$('#reorderHint'),reorderHintText=$('#reorderHintText');
var itemDialog=$('#itemDialog'),budgetDialog=$('#budgetDialog');
var fName=$('#fName'),fQty=$('#fQty'),fUnit=$('#fUnit'),fPrice=$('#fPrice'),fBudget=$('#fBudget');
function applyI18n(){document.documentElement.lang=state.lang;document.title=state.lang==='id'?'Belanja Bulanan — Rencana belanja bulanan':'Belanja Bulanan — Monthly grocery planner';document.querySelectorAll('[data-i18n]').forEach(function(el){el.textContent=T(el.getAttribute('data-i18n'));});document.querySelectorAll('[data-i18n-ph]').forEach(function(el){el.setAttribute('placeholder',T(el.getAttribute('data-i18n-ph')));});document.querySelectorAll('[data-i18n-aria]').forEach(function(el){el.setAttribute('aria-label',T(el.getAttribute('data-i18n-aria')));});document.querySelectorAll('.lang button').forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.lang===state.lang));});buildCatRadios();}
function buildCatRadios(){var ch=(document.querySelector('input[name="fCat"]:checked')||{}).value||'sembako';$('#catGrid').innerHTML=CATS.map(function(c){return '<label class="cat-opt"><input type="radio" name="fCat" value="'+c.id+'"'+(c.id===ch?' checked':'')+'><span class="cat-pill"><span aria-hidden="true">'+c.emoji+'</span>'+esc(c.label[state.lang])+'</span></label>';}).join('');}
function buildStatic(){fUnit.innerHTML=UNITS.map(function(u){return '<option value="'+u+'">'+u+'</option>';}).join('');$('#presets').innerHTML=BUDGET_PRESETS.map(function(v){return '<button type="button" class="chip num" data-preset="'+v+'">'+fmt(v)+'</button>';}).join('');}
function renderHeader(){$('#monthLong').textContent=monthLabel(view.key,false);$('#monthShort').textContent=monthLabel(view.key,true);}
function renderSummary(){var m=cur(),t=totals(m);$('#heroTitle').textContent=T('heroTitle',monthLabel(view.key,false));$('#heroSub').textContent=!t.count?T('heroSubEmpty'):(t.done===t.count?T('heroSubDone',t.count):T('heroSub',t.done,t.count));$('#budgetValue').textContent=fmt(m.budget);var b=m.budget>0?m.budget:0;var sp=b?Math.min(100,t.spent/b*100):0;var pp=b?Math.min(100,t.planned/b*100):0;var over=t.planned>m.budget;$('#barSpent').style.width=sp+'%';$('#barRest').style.width=Math.max(0,pp-sp)+'%';$('#bar').classList.toggle('over',over);$('#bar').setAttribute('aria-label',T('aBar',fmt(t.spent),fmt(t.planned),fmt(m.budget)));$('#barPct').textContent=T('barPct',b?Math.round(t.planned/b*100):0);var remain=m.budget-t.planned;$('#statRemain').classList.toggle('over',over);$('#remainLabel').textContent=over?T('over'):T('remaining');$('#remainValue').textContent=fmt(Math.abs(remain));$('#remainHint').textContent=over?T('overHint'):T('remainingHint');$('#plannedValue').textContent=fmt(t.planned);$('#plannedHint').textContent=T('plannedHint',t.count);$('#spentValue').textContent=fmt(t.spent);$('#spentHint').textContent=T('spentHint',b?Math.round(t.spent/b*100):0);var c=$('#listCount');c.hidden=!t.count;c.textContent=T('listCount',t.done,t.count);}
function renderChips(){var m=cur(),counts={};m.items.forEach(function(it){counts[it.cat]=(counts[it.cat]||0)+1;});if(view.cat!=='all'&&!counts[view.cat]) view.cat='all';var h='<button type="button" class="chip" data-cat="all" data-fid="chip-all" aria-pressed="'+(view.cat==='all')+'">'+esc(T('all'))+'<span class="chip-count num">'+m.items.length+'</span></button>';CATS.forEach(function(c){if(!counts[c.id]) return;h+='<button type="button" class="chip" data-cat="'+c.id+'" data-fid="chip-'+c.id+'" aria-pressed="'+(view.cat===c.id)+'"><span aria-hidden="true">'+c.emoji+'</span>'+esc(c.label[state.lang])+'<span class="chip-count num">'+counts[c.id]+'</span></button>';});chipsEl.innerHTML=h;}
function getFiltered(){var m=cur(),q=view.q.trim().toLowerCase();return m.items.filter(function(it){if(view.cat!=='all'&&it.cat!==view.cat) return false;if(view.hideDone&&it.done) return false;if(q&&nameOf(it).toLowerCase().indexOf(q)===-1) return false;return true;});}
function itemHTML(it){var name=nameOf(it),step=stepOf(it.unit),id=esc(it.id);var upDis=it.qty<=step?' disabled':'';return '<li class="item'+(it.done?' is-done':'')+(it.id===lastAddedId?' is-new':'')+'" data-item="'+id+'" data-cat="'+esc(it.cat)+'">'
+'<button type="button" class="drag-handle" data-drag-id="'+id+'" data-fid="drag-'+id+'" aria-label="'+esc(T('aDrag',name))+'" title="'+esc(T('reorderHint'))+'">'+ICON.grip+'</button>'
+'<label class="check"><input type="checkbox" data-act="toggle" data-id="'+id+'" data-fid="t-'+id+'"'+(it.done?' checked':'')+'><span class="check-box" aria-hidden="true">'+ICON.check+'</span><span class="sr-only">'+esc(T('aToggle',name))+'</span></label>'
+'<div class="item-main"><span class="item-name">'+esc(name)+'</span><span class="item-meta num">'+fmt(it.price)+' / '+esc(it.unit)+'</span></div>'
+'<div class="stepper"><button type="button" data-act="dec" data-id="'+id+'" data-fid="d-'+id+'"'+upDis+' aria-label="'+esc(T('aDec',name))+'">'+ICON.minus+'</button><span class="qty num">'+fmtQty(it.qty)+' '+esc(it.unit)+'</span><button type="button" data-act="inc" data-id="'+id+'" data-fid="i-'+id+'" aria-label="'+esc(T('aInc',name))+'">'+ICON.plus+'</button></div>'
+'<div class="item-price num">'+fmt(it.qty*it.price)+'</div>'
+'<div class="item-actions"><button type="button" class="icon-btn" data-act="edit" data-id="'+id+'" data-fid="e-'+id+'" aria-label="'+esc(T('aEdit',name))+'">'+ICON.edit+'</button><button type="button" class="icon-btn danger" data-act="del" data-id="'+id+'" data-fid="x-'+id+'" aria-label="'+esc(T('aDel',name))+'">'+ICON.trash+'</button></div></li>';}
function renderList(){var m=cur(),has=m.items.length>0;$('#listTools').hidden=!has;$('#listFoot').hidden=!has;destroySortables();updateSortUI();if(!has){var pk=prevKeyWithItems();var ck=pk||shiftKey(view.key,-1);listEl.innerHTML='<div class="empty"><div class="empty-art" aria-hidden="true">'+ICON.basket+'</div><h3>'+esc(T('emptyTitle'))+'</h3><p>'+esc(T('emptySub'))+'</p><div class="empty-actions">'+'<button type="button" class="btn '+(pk?'btn-primary':'btn-soft')+'" data-act="copy-prev" data-key="'+ck+'">'+esc(T('copyPrev',monthLabel(ck,false)))+'</button>'+'<button type="button" class="btn '+(pk?'btn-soft':'btn-primary')+'" data-act="starter">'+esc(T('useStarter'))+'</button><button type="button" class="btn btn-soft" data-act="csv-open">'+esc(T('csvImport'))+'</button></div></div>';return;}
var filtered=getFiltered();
var doneF=filtered.filter(function(it){return it.done;}).length;
if(filtered.length){bulkBar.style.display='';bulkToggle.checked=filtered.length>0&&doneF===filtered.length;bulkToggle.indeterminate=doneF>0&&doneF<filtered.length;bulkLabel.textContent=T('checkAll');bulkCount.textContent=T('listCount',doneF,filtered.length);reorderHint.style.display=(view.sort==='cat'&&filtered.length>1)?'':'none';reorderHintText.textContent=T('reorderHint');}else{bulkBar.style.display='none';reorderHint.style.display='none';}
if(!filtered.length){listEl.innerHTML='<div class="empty"><div class="empty-art" aria-hidden="true">'+ICON.basket+'</div><h3>'+esc(T('noMatch'))+'</h3><p>'+esc(T('noMatchSub'))+'</p><div class="empty-actions"><button type="button" class="btn btn-soft" data-act="clear">'+esc(T('clearFilter'))+'</button></div></div>';return;}
var html='';if(view.sort!=='cat'){var flat=filtered.slice();if(view.sort==='az') flat.sort(function(a,b){return nameOf(a).localeCompare(nameOf(b),state.lang==='id'?'id':'en',{sensitivity:'base'});});else if(view.sort==='priceDesc') flat.sort(function(a,b){return b.price-a.price;});else flat.sort(function(a,b){return a.price-b.price;});html='<section class="group" data-group="all"><div class="group-head"><span class="badge" style="background:var(--lav-soft)" aria-hidden="true">↕</span><h3 class="group-name">'+esc(T('sortAllTitle'))+'</h3><span class="group-count">'+esc(T('items',flat.length))+'</span></div><ul class="items" data-cat="all">'+flat.map(itemHTML).join('')+'</ul></section>';listEl.innerHTML=html;return;}CATS.forEach(function(c){var its=filtered.filter(function(it){return it.cat===c.id;});if(!its.length) return;var sum=its.reduce(function(s,it){return s+it.qty*it.price;},0);html+='<section class="group" data-group="'+c.id+'"><div class="group-head"><span class="badge" style="background:'+c.soft+'" aria-hidden="true">'+c.emoji+'</span><h3 class="group-name">'+esc(c.label[state.lang])+'</h3><span class="group-count">'+esc(T('items',its.length))+'</span><button type="button" class="icon-btn small" data-act="cat-toggle" data-cat="'+c.id+'" data-fid="cat-'+c.id+'" aria-label="'+esc(T('aCatToggle',c.label[state.lang]))+'" title="'+esc(T('checkAll'))+'">'+ICON.checkAll+'</button><button type="button" class="group-add" data-act="cat-add" data-cat="'+c.id+'" data-fid="catadd-'+c.id+'" aria-label="'+esc(T('aCatAdd',c.label[state.lang]))+'" title="'+esc(T('aCatAdd',c.label[state.lang]))+'">'+ICON.plus+'<span>'+esc(T('catAdd'))+'</span></button><span class="group-sum num">'+fmt(sum)+'</span></div><ul class="items" data-cat="'+c.id+'">'+its.map(itemHTML).join('')+'</ul></section>';});listEl.innerHTML=html;initSortables();}
function destroySortables(){sortables.forEach(function(s){try{s.destroy();}catch(e){}});sortables=[];}
function initSortables(){if(!window.Sortable) return;try{document.querySelectorAll('#list .items').forEach(function(ul){var s=new Sortable(ul,{group:'shopping',handle:'.drag-handle',animation:220,easing:'cubic-bezier(.2,.8,.2,1)',ghostClass:'sortable-ghost',chosenClass:'sortable-chosen',dragClass:'sortable-drag',delay:140,delayOnTouchOnly:true,touchStartThreshold:5,fallbackTolerance:5,scrollSensitivity:70,scrollSpeed:6,onEnd:function(evt){var li=evt.item;var id=li&&li.getAttribute?li.getAttribute('data-item'):null;var toCat=evt.to&&evt.to.getAttribute?evt.to.getAttribute('data-cat'):null;var ni=evt.newIndex;if(!id||!toCat){render();return;}relocateItem(id,toCat,ni);}});sortables.push(s);});}catch(e){}}
function relocateItem(id,toCat,newIndex){var m=cur();var oldIdx=-1;for(var i=0;i<m.items.length;i++) if(m.items[i].id===id){oldIdx=i;break;}if(oldIdx<0){render();return;}var destUl=document.querySelector('.items[data-cat="'+toCat+'"]');var visOrder=destUl?Array.prototype.map.call(destUl.querySelectorAll('[data-item]'),function(li){return li.getAttribute('data-item');}):[];var moved=m.items.splice(oldIdx,1)[0];moved.cat=toCat;var posInVis=visOrder.indexOf(id);var pred=posInVis>0?visOrder[posInVis-1]:null;var succ=(posInVis>=0&&posInVis<visOrder.length-1)?visOrder[posInVis+1]:null;var insertAt=m.items.length;if(pred){var pi=-1;for(var a=0;a<m.items.length;a++) if(m.items[a].id===pred){pi=a;break;}if(pi>=0) insertAt=pi+1;else if(succ){var si=-1;for(var b=0;b<m.items.length;b++) if(m.items[b].id===succ){si=b;break;}if(si>=0) insertAt=si;}}else if(succ){var sj=-1;for(var c2=0;c2<m.items.length;c2++) if(m.items[c2].id===succ){sj=c2;break;}if(sj>=0) insertAt=sj;}else{var order=CATS.map(function(cc){return cc.id;});var toO=order.indexOf(toCat);insertAt=m.items.length;for(var k=0;k<m.items.length;k++){if(order.indexOf(m.items[k].cat)>toO){insertAt=k;break;}}}m.items.splice(Math.max(0,Math.min(insertAt,m.items.length)),0,moved);focusFid='drag-'+id;render();}
function moveUpDown(id,dir){var m=cur();var idx=-1;for(var i=0;i<m.items.length;i++) if(m.items[i].id===id){idx=i;break;}if(idx<0) return;var cat=m.items[idx].cat;var indices=[];for(var j=0;j<m.items.length;j++) if(m.items[j].cat===cat) indices.push(j);var pos=indices.indexOf(idx);var np=pos+dir;if(np<0||np>=indices.length) return;var j2=indices[np];var tmp=m.items[idx];m.items[idx]=m.items[j2];m.items[j2]=tmp;focusFid=(dir<0?'up-':'down-')+id;render();}
function renderChart(){var m=cur();var sums=CATS.map(function(c){return {c:c,v:m.items.reduce(function(s,it){return it.cat===c.id?s+it.qty*it.price:s;},0)};}).filter(function(x){return x.v>0;}).sort(function(a,b){return b.v-a.v;});var total=sums.reduce(function(s,x){return s+x.v;},0);var R=46,C=2*Math.PI*R,off=0;var rings='<circle cx="60" cy="60" r="'+R+'" fill="none" stroke="#F1ECE4" stroke-width="15"/>';sums.forEach(function(x){var len=x.v/total*C;var gap=sums.length>1?Math.min(2.5,len*0.4):0;rings+='<circle cx="60" cy="60" r="'+R+'" fill="none" stroke="'+x.c.color+'" stroke-width="15" stroke-dasharray="'+(len-gap).toFixed(2)+' '+(C-len+gap).toFixed(2)+'" stroke-dashoffset="'+(-off).toFixed(2)+'"/>';off+=len;});var h='<div class="donut-wrap"><svg viewBox="0 0 120 120" role="img" aria-label="'+esc(T('aChart'))+'"><g transform="rotate(-90 60 60)">'+rings+'</g></svg><div class="donut-center"><span>'+esc(T('chartTotal'))+'</span><strong class="num">'+fmtShort(total)+'</strong></div></div>';if(!sums.length){h+='<p class="chart-empty">'+esc(T('chartEmpty'))+'</p>';}else{h+='<ul class="legend">'+sums.map(function(x){var p=Math.round(x.v/total*100);return '<li><span class="dot" style="background:'+x.c.color+'" aria-hidden="true"></span><span><span aria-hidden="true">'+x.c.emoji+'</span> '+esc(x.c.label[state.lang])+'</span><span class="amt num">'+fmt(x.v)+'</span><span class="pct num">'+(p<1?'&lt;1':p)+'%</span></li>';}).join('')+'</ul>';}chartEl.innerHTML=h;}
function renderQuick(){var m=cur();quickEl.innerHTML=Object.keys(STAPLES).filter(function(k){return (state.quickHidden||[]).indexOf(k)<0;}).map(function(k){var s=STAPLES[k];var ex=null;for(var i=0;i<m.items.length;i++) if(m.items[i].tpl===k){ex=m.items[i];break;}var inL=!!ex;var meta=inL?fmtQty(ex.qty)+' '+esc(ex.unit)+' · '+esc(T('inList')):fmt(s.price)+'/'+s.unit;var ml=inL?T('aQuickInc',s[state.lang]):T('aQuickAdd',s[state.lang]);var rl=T('aQuickRemove',s[state.lang]);return '<div class="quick'+(inL?' in':'')+'" data-tpl="'+k+'"><button type="button" class="quick-main" data-act="quick-main" data-tpl="'+k+'" data-fid="q-'+k+'" aria-label="'+esc(ml)+'" title="'+esc(ml)+'"><span class="quick-ic" aria-hidden="true">'+(inL?ICON.check:ICON.plus)+'</span><span class="quick-txt"><span class="quick-name">'+esc(s[state.lang])+'</span><span class="quick-meta num">'+meta+'</span></span></button>'+(inL?'<button type="button" class="quick-remove" data-act="quick-remove" data-tpl="'+k+'" data-fid="qr-'+k+'" aria-label="'+esc(rl)+'" title="'+esc(rl)+'">'+ICON.trash+'</button>':'')+'<button type="button" class="quick-remove" data-act="quick-hide" data-tpl="'+k+'" aria-label="'+esc(T('aQuickHide',s[state.lang]))+'" title="'+esc(T('aQuickHide',s[state.lang]))+'"><svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 6.5l11 11M17.5 6.5l-11 11"/></svg></button></div>';}).join('')+customQuickHTML();updateQuickActions();}
function updateQuickActions(){var m=cur();var hasQ=m.items.some(function(it){return it.tpl||it.qid;});var hid=(state.quickHidden||[]).length;var a=document.getElementById('quickAddBtn'),c=document.getElementById('quickClearBtn'),r=document.getElementById('quickRestoreBtn');var lbl=document.getElementById('quickAddLbl');if(lbl) lbl.textContent=T('quickAddBtn');if(c){c.hidden=!hasQ;c.textContent=T('quickClearAll');}if(r){r.hidden=!hid;r.textContent=T('quickRestore',hid);}}
function quickClearAll(){var m=cur();var pairs=[];m.items.forEach(function(it,i){if(it.tpl||it.qid) pairs.push({i:i,it:it});});if(!pairs.length) return;var mk=view.key;m.items=m.items.filter(function(it){return !(it.tpl||it.qid);});render();toast(T('tQuickCleared',pairs.length),T('undo'),function(){var mm=state.months[mk];if(!mm) return;pairs.slice().sort(function(a,b){return a.i-b.i;}).forEach(function(p){mm.items.splice(Math.min(p.i,mm.items.length),0,p.it);});render();});}
function customQuickHTML(){var m=cur();return (state.quick||[]).map(function(q){var ex=null;for(var i=0;i<m.items.length;i++) if(m.items[i].qid===q.id){ex=m.items[i];break;}var inL=!!ex;var id=esc(q.id);var meta=inL?fmtQty(ex.qty)+' '+esc(ex.unit)+' · '+esc(T('inList')):fmt(q.price)+'/'+esc(q.unit);var ml=inL?T('aQuickInc',q.name):T('aQuickAdd',q.name);var rl=T('aQuickRemove',q.name);var dl=T('aQuickDelete',q.name);return '<div class="quick custom'+(inL?' in':'')+'" data-tpl="c:'+id+'"><button type="button" class="quick-main" data-act="quick-main" data-tpl="c:'+id+'" aria-label="'+esc(ml)+'" title="'+esc(ml)+'"><span class="quick-ic" aria-hidden="true">'+(inL?ICON.check:ICON.plus)+'</span><span class="quick-txt"><span class="quick-name">'+esc(q.name)+'</span><span class="quick-meta num">'+meta+'</span></span></button>'+(inL?'<button type="button" class="quick-remove" data-act="quick-remove" data-tpl="c:'+id+'" aria-label="'+esc(rl)+'" title="'+esc(rl)+'">'+ICON.trash+'</button>':'')+'<button type="button" class="quick-remove" data-act="quick-del" data-tpl="c:'+id+'" aria-label="'+esc(dl)+'" title="'+esc(dl)+'"><svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 6.5l11 11M17.5 6.5l-11 11"/></svg></button></div>';}).join('');}
var quickPending=false;
function customQuick(act,id){var q=null;(state.quick||[]).forEach(function(x){if(x.id===id) q=x;});if(!q) return;var m=cur();if(act==='quick-del'){state.quick=state.quick.filter(function(x){return x.id!==id;});render();toast(T('tQuickDeleted',q.name));return;}if(act==='quick-remove'){var pairs=[];m.items.forEach(function(it,i){if(it.qid===id) pairs.push({i:i,it:it});});if(!pairs.length) return;var mk=view.key;m.items=m.items.filter(function(it){return it.qid!==id;});render();toast(T('tQuickRemoved',q.name),T('undo'),function(){var mm=state.months[mk];if(!mm) return;pairs.slice().sort(function(a,b){return a.i-b.i;}).forEach(function(p){mm.items.splice(Math.min(p.i,mm.items.length),0,p.it);});render();});return;}var ex=null;for(var i=0;i<m.items.length;i++) if(m.items[i].qid===id){ex=m.items[i];break;}if(ex){ex.qty=round2(ex.qty+stepOf(ex.unit));render();toast(T('tQtyUp',q.name));}else{var item={id:uid(),name:q.name,cat:q.cat,qty:1,unit:q.unit,price:q.price,done:false,qid:id};m.items.push(item);lastAddedId=item.id;if(view.cat!=='all'&&view.cat!==item.cat) view.cat='all';if(view.q){view.q='';searchEl.value='';}render();toast(T('tAdded',q.name));}}
function shareText(){var m=cur(),lines=['🛒 '+T('heroTitle',monthLabel(view.key,false)),''];CATS.forEach(function(c){var its=m.items.filter(function(it){return it.cat===c.id;});if(!its.length) return;lines.push(c.emoji+' '+c.label[state.lang]);its.forEach(function(it){lines.push((it.done?'✓ ':'• ')+nameOf(it)+' — '+fmtQty(it.qty)+' '+it.unit);});lines.push('');});lines.push(T('planned')+': '+fmt(totals(m).planned));return lines.join('\n');}
function renderActions(){var m=cur();$('#waBtn').href='https://wa.me/?text='+encodeURIComponent(shareText());var anyDone=m.items.some(function(it){return it.done;});var allDone=m.items.length>0&&m.items.every(function(it){return it.done;});$('#uncheckBtn').disabled=!anyDone;$('#checkAllBtn').disabled=!m.items.length||allDone;$('#storeNote').textContent=T(storageOk?'storeOk':'storeOff');$('#foot').classList.toggle('off',!storageOk);}
function render(){var a=document.activeElement;var fid=focusFid||(a&&a.dataset?a.dataset.fid:null);focusFid=null;renderHeader();renderSummary();renderChips();renderList();renderChart();renderQuick();save();renderActions();if(fid){var el=document.querySelector('[data-fid="'+fid+'"]');if(el&&!el.disabled){try{el.focus({preventScroll:true});}catch(e){el.focus();}}}if(lastAddedId){var row=document.querySelector('[data-item="'+lastAddedId+'"]');if(row&&row.scrollIntoView){var calm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;try{row.scrollIntoView({block:'nearest',behavior:calm?'auto':'smooth'});}catch(e){}}lastAddedId=null;}}
var toastTimer=null,toastEl=$('#toast'),toastAction=$('#toastAction');
function hideToast(){toastEl.classList.remove('show');}
function toast(msg,al,fn){$('#toastMsg').textContent=msg;if(al){toastAction.hidden=false;toastAction.textContent=al;toastAction.onclick=function(){hideToast();fn();};}else{toastAction.hidden=true;toastAction.onclick=null;}toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,al?6500:3200);}
function openDialog(d){if(typeof d.showModal==='function'){if(!d.open) d.showModal();}else d.setAttribute('open','');document.documentElement.classList.add('modal-open');}
function closeDialog(d){if(typeof d.close==='function'){if(d.open) d.close();}else{d.removeAttribute('open');document.documentElement.classList.remove('modal-open');}}
[itemDialog,budgetDialog].forEach(function(d){d.addEventListener('close',function(){document.documentElement.classList.remove('modal-open');});d.addEventListener('click',function(e){if(e.target===d) closeDialog(d);var c=e.target.closest?e.target.closest('[data-close]'):null;if(c) closeDialog(d);});});
function setErr(inp,err,msg){if(msg){inp.setAttribute('aria-invalid','true');err.textContent=msg;err.hidden=false;}else{inp.removeAttribute('aria-invalid');err.hidden=true;err.textContent='';}}
function updateSubtotal(){var q=parseFloat(fQty.value);var p=Number(digitsOnly(fPrice.value))||0;$('#fSubtotal').textContent=fmt((q>0?q:0)*p);}
function setCatRadio(cat){document.querySelectorAll('input[name="fCat"]').forEach(function(r){r.checked=r.value===cat;});}
function openItemDialog(it,defaultCat){editingId=it?it.id:null;quickPending=false;$('#quickHint').hidden=true;$('#itemDialogTitle').textContent=T(it?'editTitle':'addTitle');setErr(fName,$('#fNameErr'),'');setErr(fQty,$('#fQtyErr'),'');if(it){fName.value=nameOf(it);setCatRadio(it.cat);fQty.value=round2(it.qty);if(UNITS.indexOf(it.unit)===-1){var o=document.createElement('option');o.value=it.unit;o.textContent=it.unit;fUnit.appendChild(o);}fUnit.value=it.unit;fPrice.value=it.price?dots(it.price):'';}else{fName.value='';setCatRadio(defaultCat||(view.cat!=='all'?view.cat:'sembako'));fQty.value=1;fUnit.value='pcs';fPrice.value='';}updateSubtotal();openDialog(itemDialog);setTimeout(function(){fName.focus();if(it) fName.select();},30);}
$('#prevMonth').addEventListener('click',function(){changeMonth(-1);});
$('#nextMonth').addEventListener('click',function(){changeMonth(1);});
function changeMonth(d){view.key=shiftKey(view.key,d);view.cat='all';view.q='';searchEl.value='';render();}
document.querySelectorAll('.lang button').forEach(function(b){b.addEventListener('click',function(){if(state.lang===b.dataset.lang) return;state.lang=b.dataset.lang;applyI18n();render();});});
