listEl.addEventListener('keydown',function(e){var h=e.target.closest?e.target.closest('.drag-handle'):null;if(!h) return;var id=h.getAttribute('data-drag-id');if(!id) return;if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();moveUpDown(id,e.key==='ArrowUp'?-1:1);}else if(e.key==='Home'||e.key==='End'){e.preventDefault();var m=cur();var it=findItem(id);if(!it) return;var cat=it.cat;var idx=m.items.indexOf(it);m.items.splice(idx,1);if(e.key==='Home'){var ni=m.items.findIndex(function(x){return x.cat===cat;});m.items.splice(ni<0?0:ni,0,it);}else{var last=-1;for(var i=0;i<m.items.length;i++) if(m.items[i].cat===cat) last=i;m.items.splice(last<0?Math.min(idx,m.items.length):last+1,0,it);}focusFid='drag-'+id;render();}});
listEl.addEventListener('click',function(e){var b=e.target.closest('button[data-act]');if(!b) return;var act=b.dataset.act,m=cur();if(act==='copy-prev'){var src=state.months[b.dataset.key];if(!src||!Array.isArray(src.items)||!src.items.length){toast(T('tCopyNone'));return;}m.items=src.items.map(function(it){var cp=Object.assign({},it);cp.id=uid();cp.done=false;return cp;});m.budget=src.budget||m.budget;render();toast(T('tCopiedPrev'));return;}if(act==='csv-open'){openDialog(csvDialog);return;}if(act==='starter'){m.items=STARTER.map(function(k){return fromTpl(k);});render();toast(T('tStarter'));return;}if(act==='clear'){view.cat='all';view.q='';view.hideDone=false;searchEl.value='';hideDoneEl.checked=false;render();return;}if(act==='cat-add'){openItemDialog(null,b.dataset.cat);return;}if(act==='cat-toggle'){var cat=b.dataset.cat;var its=m.items.filter(function(it){return it.cat===cat;});if(!its.length) return;var allD=its.every(function(it){return it.done;});var snap2=snapshotDone();its.forEach(function(it){it.done=!allD;});focusFid='cat-'+cat;render();toast(!allD?T('tCheckedAll'):T('tUnchecked'),T('undo'),function(){restoreDone(snap2);});return;}var it=findItem(b.dataset.id);if(!it) return;var step=stepOf(it.unit);if(act==='inc'){it.qty=round2(it.qty+step);render();}else if(act==='dec'){it.qty=Math.max(step,round2(it.qty-step));render();}else if(act==='up'){moveUpDown(it.id,-1);}else if(act==='down'){moveUpDown(it.id,1);}else if(act==='edit'){openItemDialog(it);}else if(act==='del'){var key=view.key,idx=m.items.indexOf(it),name=nameOf(it);m.items.splice(idx,1);render();toast(T('tDeleted',name),T('undo'),function(){var mm=state.months[key];if(!mm) return;mm.items.splice(Math.min(idx,mm.items.length),0,it);if(view.key===key) lastAddedId=it.id;render();});}});
quickEl.addEventListener('click',function(e){var b=e.target.closest('button[data-act]');if(!b) return;if((b.dataset.tpl||'').indexOf('c:')===0){customQuick(b.dataset.act,b.dataset.tpl.slice(2));return;}var k=b.dataset.tpl,s=STAPLES[k];if(!s) return;var act=b.dataset.act,m=cur();if(act==='quick-hide'){state.quickHidden=(state.quickHidden||[]).concat([k]);render();toast(T('tQuickHidden',s[state.lang]));return;}if(act==='quick-remove'){var pairs=[];m.items.forEach(function(it,i){if(it.tpl===k) pairs.push({i:i,it:it});});if(!pairs.length) return;var mk=view.key;m.items=m.items.filter(function(it){return it.tpl!==k;});focusFid=(view.key===mk)?'q-'+k:null;render();toast(T('tQuickRemoved',s[state.lang]),T('undo'),function(){var mm=state.months[mk];if(!mm) return;pairs.slice().sort(function(a,b2){return a.i-b2.i;}).forEach(function(p){mm.items.splice(Math.min(p.i,mm.items.length),0,p.it);});if(view.key===mk) focusFid='qr-'+k;render();});return;}var ex=null;for(var i=0;i<m.items.length;i++) if(m.items[i].tpl===k){ex=m.items[i];break;}if(ex){ex.qty=round2(ex.qty+stepOf(ex.unit));render();toast(T('tQtyUp',s[state.lang]));}else{var item=fromTpl(k);m.items.push(item);lastAddedId=item.id;if(view.cat!=='all'&&view.cat!==item.cat) view.cat='all';if(view.q){view.q='';searchEl.value='';}render();toast(T('tAdded',s[state.lang]));}});
