$('#itemForm').addEventListener('submit',function(e){e.preventDefault();var name=fName.value.trim();var qty=parseFloat(fQty.value);var price=Number(digitsOnly(fPrice.value))||0;var cat=(document.querySelector('input[name="fCat"]:checked')||{}).value||'sembako';var unit=fUnit.value||'pcs';var bad=null;if(!name){setErr(fName,$('#fNameErr'),T('errName'));bad=bad||fName;}if(!(qty>0)){setErr(fQty,$('#fQtyErr'),T('errQty'));bad=bad||fQty;}if(bad){bad.focus();return;}qty=round2(qty);var m=cur();if(editingId){var it=findItem(editingId);if(it){if(name!==nameOf(it)){it.name=name;delete it.tpl;}it.cat=cat;it.qty=qty;it.unit=unit;it.price=price;}closeDialog(itemDialog);render();toast(T('tSaved'));}else{var ni={id:uid(),name:name,cat:cat,qty:qty,unit:unit,price:price,done:false};if(quickPending){ni.qid=uid();state.quick=(state.quick||[]).concat([{id:ni.qid,name:name,cat:cat,unit:unit,price:price}]);quickPending=false;}m.items.push(ni);lastAddedId=ni.id;if(view.cat!=='all'&&view.cat!==cat) view.cat='all';if(view.q){view.q='';searchEl.value='';}closeDialog(itemDialog);render();toast(T('tAdded',name));}editingId=null;});
$('#editBudget').addEventListener('click',function(){var m=cur();fBudget.value=m.budget?dots(m.budget):'';setErr(fBudget,$('#fBudgetErr'),'');openDialog(budgetDialog);setTimeout(function(){fBudget.focus();fBudget.select();},30);});
