I18N.id.csvImport='Impor CSV';I18N.id.tCsvImported=function(a,s){return a+' barang dari CSV udah masuk daftar'+(s?' ('+s+' baris dilewati)':'')+'!';};I18N.id.tCsvEmpty='File CSV-nya kosong atau nggak kebaca';I18N.en.csvImport='Import CSV';I18N.en.tCsvImported=function(a,s){return a+' items imported from CSV'+(s?' ('+s+' rows skipped)':'')+'.';};I18N.en.tCsvEmpty='The CSV file is empty or unreadable';
function parseCSV(text){var rows=[],row=[],cell='',q=false;for(var i=0;i<text.length;i++){var c=text[i];if(q){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else q=false;}else cell+=c;}else if(c==='"'){q=true;}else if(c===','||c===';'){row.push(cell);cell='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n') i++;row.push(cell);cell='';rows.push(row);row=[];}else cell+=c;}if(cell!==''||row.length){row.push(cell);rows.push(row);}return rows.filter(function(r){return r.some(function(x){return String(x).trim();});});}
function importCSV(text){var rows=parseCSV(text);if(!rows.length){toast(T('tCsvEmpty'));return;}var head=rows[0].map(function(h){return String(h).trim().toLowerCase();});var hasHead=head.some(function(h){return ['name','nama','item','barang'].indexOf(h)>-1;});function col(names,def){if(!hasHead) return def;for(var i=0;i<head.length;i++) if(names.indexOf(head[i])>-1) return i;return -1;}var cN=col(['name','nama','item','barang'],0),cC=col(['category','kategori','cat'],1),cQ=col(['qty','jumlah','quantity'],2),cU=col(['unit','satuan'],3),cP=col(['price','harga'],4);var body=hasHead?rows.slice(1):rows;var m=cur(),added=0,skipped=0;body.forEach(function(r){var name=cN<0?'':String(r[cN]||'').trim();if(!name){skipped++;return;}var catRaw=cC<0?'':String(r[cC]||'').trim().toLowerCase();var cat='other';CATS.forEach(function(c){if(c.id===catRaw||c.label.id.toLowerCase()===catRaw||c.label.en.toLowerCase()===catRaw) cat=c.id;});var qty=round2(parseFloat(String(cQ<0?'':r[cQ]||'').replace(',','.')));if(!(qty>0)) qty=1;var unit=(cU<0?'':String(r[cU]||'').trim())||'pcs';var price=Number(String(cP<0?'':r[cP]||'').replace(/\D/g,''))||0;m.items.push({id:uid(),name:name,cat:cat,qty:qty,unit:unit,price:price,done:false});added++;});if(!added){toast(T('tCsvEmpty'));return;}lastAddedId=null;render();toast(T('tCsvImported',added,skipped));}
