$('#copyBtn').addEventListener('click',function(){var text=shareText();function done(ok){toast(T(ok?'tCopied':'tCopyFail'));}function fb(){try{var ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.cssText='position:fixed;top:0;left:0;opacity:0;';document.body.appendChild(ta);ta.select();var ok=document.execCommand('copy');document.body.removeChild(ta);done(ok);}catch(err){done(false);}}if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(function(){done(true);},fb);}else fb();});
